// src/message-mutation.ts
function validateTrackedBotMessageScope(args) {
  const tracked = args.botMessageTracker?.get(args.messageId);
  if (!tracked) {
    return {
      ok: false,
      message: `${args.toolName} denied: ${args.messageId} is not a tracked bot message.`
    };
  }
  if (tracked.chatId !== args.chatId || (tracked.threadId ?? "") !== (args.threadId ?? "")) {
    return {
      ok: false,
      message: `${args.toolName} denied: ${args.messageId} belongs to chat=${tracked.chatId ?? "(unknown)"} thread=${tracked.threadId ?? "(none)"}, does not belong to chat=${args.chatId} thread=${args.threadId ?? "(none)"}.`
    };
  }
  return { ok: true };
}

